import subprocess
import time
import json
import platform
LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("Interval and duration must be greater than zero")
    command = ['typeperf', '\\Processor(_Total)\\% Processor Time', '-sc', '1'] if platform.system() == 'Windows' else ['mpstat', '1', '1']
    cpu_data = []
    start_time = time.time()
    while time.time() - start_time < duration:
        try:
            output = subprocess.check_output(command, stderr=subprocess.DEVNULL, text=True, shell=True)
            timestamp = time.strftime('%Y-%m-%d %H:%M:%S', time.localtime())
            if platform.system() == 'Windows':
                usage = float(output.strip().splitlines()[-1].split(',')[-1].replace('"', ''))
            else:
                usage = 100 - float(output.strip().splitlines()[-1].split()[-1])
            cpu_data.append({'timestamp': timestamp, 'cpu_usage': usage})
        except Exception:
            pass
        time.sleep(interval)
    try:
        with open(LOGFILE_PATH, 'w') as log_file:
            json.dump(cpu_data, log_file)
    except IOError:
        return None
    return LOGFILE_PATH

