import os
import threading
def task_func(script_path: str, timeout: int = 60) -> str:
    if not isinstance(script_path, str):
        raise TypeError("script_path must be a string")
    if not os.path.exists(script_path):
        raise FileNotFoundError("The script file does not exist")

    result = {"message": None}

    def run_script():
        try:
            process = subprocess.Popen(['python', script_path], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
            process.wait()
            result["message"] = "Script executed successfully." if process.returncode == 0 else "Execution failed."
        except Exception:
            result["message"] = "Execution failed."

    thread = threading.Thread(target=run_script)
    thread.start()
    thread.join(timeout)

    if thread.is_alive():
        process.terminate()
        thread.join()
        return "Terminating process due to timeout."
    return result["message"]

